import {e} from './ui.mjs?v=20261117fast';
const module=(title,body)=>`<details class="editor-module"><summary>${e(title)}</summary><div>${body}</div></details>`;
export function teamEditor(d,{input,block,image,photos}){
 const visible=(id,label)=>`<label class="consent"><input type="checkbox" data-team-visible="${id}" ${d.team.hiddenSections.includes(id)?'':'checked'}>${label}</label>`;
 return module('1. Portada · foto de pantalla completa',visible('cover','Mostrar foto de portada')+image('team.cover','Foto de portada')+input('team.heroEyebrow','Texto pequeño sobre el título')+input('team.title','Título sobre la foto',{area:true})+input('team.intro','Texto sobre la foto',{area:true}))+
 module('2. Nuestra historia · texto y fotos',input('team.photosTitle','Título')+input('team.paragraphs','Historia · un párrafo por línea',{lines:true})+visible('photos','Mostrar fotos de la historia')+d.team.photos.map((_,i)=>image(`team.photos.${i}`,'Foto del equipo '+(i+1))).join(''))+
 module('3. Alberto y Renata · perfiles',input('team.membersTitle','Título del módulo')+d.team.members.map((p,i)=>block(p.name,input(`team.members.${i}.name`,'Nombre')+image(`team.members.${i}.photo`,'Retrato')+input(`team.members.${i}.bio`,'Presentación',{area:true})+input(`team.members.${i}.contactLabel`,'Texto del botón de contacto')+input(`team.members.${i}.contact`,'Destino del contacto HTTPS')+input(`team.members.${i}.phone`,'Teléfono'))).join(''))+
 module('4. Cómo te acompañamos',visible('approach','Mostrar módulo')+input('team.approachTitle','Título')+d.team.approach.map((_,i)=>block('Contenido '+(i+1),input(`team.approach.${i}.title`,'Título')+input(`team.approach.${i}.text`,'Texto',{area:true}))).join(''))+
 module('Galería de fotos 1 · hasta 8 fotos',visible('cappers','Mostrar galería')+input('team.galleryTitle','Título')+input('team.galleryIntro','Texto',{area:true})+photos('team.gallery',8))+
 module('Galería de fotos 2 · hasta 2 fotos',visible('national','Mostrar galería')+input('team.nationalAward.title','Título')+input('team.nationalAward.description','Texto',{area:true})+photos('team.nationalAward.photos',2));
}
export function serviceEditor(tab,d,{input,block,image}){
 const index=d.services.findIndex(s=>s.id===tab),s=d.services[index],p='services.'+index;
 const visible=id=>input(p+'.visibility.'+id,'Mostrar este módulo',{check:true});
 const questions=()=>s.faq.map((q,i)=>module(q.question||'Nueva pregunta',input(`${p}.faq.${i}.visible`,'Mostrar pregunta',{check:true})+input(`${p}.faq.${i}.question`,'Pregunta')+input(`${p}.faq.${i}.answer`,'Respuesta',{area:true})+`<button type="button" class="text-button danger" data-delete-question="${p}.faq" data-index="${i}">Eliminar pregunta</button>`)).join('')+`<button type="button" class="button button-outline" data-add-question="${p}.faq">Agregar pregunta</button>`;
 return '<p>Los módulos están en el mismo orden que en la página. Desmarcar su visibilidad conserva el contenido.</p>'+module('1. Portada',visible('hero')+input(p+'.title','Título',{area:true})+input(p+'.intro','Texto',{area:true})+image(p+'.image','Foto principal')+input(p+'.cta','Texto del botón')+input(p+'.buttonHref','Página de destino del botón'))+
 (tab==='rentar'?s.audiences.map((a,i)=>module(a.title,input(`${p}.audiences.${i}.visible`,'Mostrar módulo',{check:true})+input(`${p}.audiences.${i}.title`,'Título')+input(`${p}.audiences.${i}.intro`,'Texto',{area:true})+input(`${p}.audiences.${i}.items`,'Puntos · uno por línea',{lines:true})+input(`${p}.audiences.${i}.buttonLabel`,'Texto del botón')+input(`${p}.audiences.${i}.buttonHref`,'Página de destino del botón'))).join(''):'')+
 module('Tabla comparativa · widget',visible('comparison')+input(p+'.comparison.title','Título',{area:true})+input(p+'.comparison.soloLabel','Encabezado de primera columna')+input(p+'.comparison.teamLabel','Encabezado de segunda columna')+(s.comparison?.rows||[]).map((r,i)=>block('Fila '+(i+1),input(`${p}.comparison.rows.${i}.0`,'Tema')+input(`${p}.comparison.rows.${i}.1`,'Primera columna',{area:true})+input(`${p}.comparison.rows.${i}.2`,'Segunda columna',{area:true})+`<button type="button" class="text-button danger" data-delete-row="${p}.comparison.rows" data-index="${i}">Eliminar fila</button>`)).join('')+`<button type="button" class="button button-outline" data-add-row="${p}.comparison.rows">Agregar fila</button>`)+
 module('Tu proyecto marca la estrategia · tres fases',visible('process')+input(p+'.processTitle','Frase principal',{area:true})+s.process.map((step,i)=>block('Fase '+(i+1),image(`${p}.process.${i}.image`,'Foto de la fase')+input(`${p}.process.${i}.title`,'Título')+input(`${p}.process.${i}.text`,'Texto',{area:true})+input(`${p}.process.${i}.items`,'Puntos · uno por línea',{lines:true}))).join(''))+
 module('Antes de dar el siguiente paso · desplegables',visible('reading')+input(p+'.readingTitle','Título del módulo')+s.sections.map((section,i)=>block('Desplegable '+(i+1),input(`${p}.sections.${i}.visible`,'Mostrar desplegable',{check:true})+input(`${p}.sections.${i}.title`,'Título')+input(`${p}.sections.${i}.text`,'Descripción',{area:true})+`<button type="button" class="text-button danger" data-delete-reading="${p}.sections" data-index="${i}">Eliminar desplegable</button>`)).join('')+`<button type="button" class="button button-outline" data-add-reading="${p}.sections">Agregar desplegable</button>`)+
 module('Las preguntas que sí importan',visible('faq')+input(p+'.faqConfig.title','Título')+input(p+'.faqConfig.intro','Texto',{area:true})+questions())+
 module('Mi proyecto · formulario',visible('project')+input(p+'.project.title','Título',{area:true})+input(p+'.project.intro','Texto',{area:true})+input(p+'.project.formTitle','Título del formulario')+input(p+'.project.buttonLabel','Texto del botón de envío'));
}
export function postsEditor(d,{input,block,image}){
 const prefix=typeof location==='undefined'?'articulo.html?slug=':new URL('articulo.html',location.href).href+'?slug=';
 return block('Pantalla del blog',input('blogPage.title','Título principal',{area:true})+input('blogPage.intro','Descripción',{area:true})+input('blogPage.listTitle','Título del listado')+input('blogPage.listIntro','Descripción del listado',{area:true}))+
 block('Orden de artículos','<p>El primero de esta lista aparece primero en el blog. Los nuevos se agregan arriba.</p>'+d.posts.map((p,i)=>`<div class="version-row"><span>${e(p.title)} · ${p.published?'Visible':'Oculto'}</span><div><button type="button" class="text-button" data-post-move="${i}" data-dir="-1" ${i===0?'disabled':''} aria-label="Subir artículo">↑</button><button type="button" class="text-button" data-post-move="${i}" data-dir="1" ${i===d.posts.length-1?'disabled':''} aria-label="Bajar artículo">↓</button></div></div>`).join(''))+
 '<button type="button" class="button" data-new-post>Crear artículo</button>'+d.posts.map((p,i)=>`<details class="admin-post"><summary>${e(p.title)} · ${p.published?'Visible':'Oculto'}</summary>${input(`posts.${i}.published`,'Mostrar artículo',{check:true})+input(`posts.${i}.title`,'Título')}<div class="editor-permalink"><span>${e(prefix)}</span>${input(`posts.${i}.slug`,'Nombre de la página · usa palabras separadas por guiones')}</div>${input(`posts.${i}.category`,'Tema')+input(`posts.${i}.excerpt`,'Descripción breve',{area:true})+image(`posts.${i}.cover`,'Portada')+input(`posts.${i}.author`,'Autor')+input(`posts.${i}.updated`,'Fecha',{type:'date'})}${p.sections.map((s,j)=>block('Sección '+(j+1),input(`posts.${i}.sections.${j}.title`,'Título')+input(`posts.${i}.sections.${j}.text`,'Contenido',{area:true})+`<button type="button" class="text-button danger" data-delete-section="${i},${j}">Eliminar sección</button>`)).join('')}<button type="button" class="button button-outline" data-new-section="${i}">Agregar sección</button><button type="button" class="text-button danger" data-delete-post="${i}">Eliminar artículo</button></details>`).join('');
}
export function reviewsEditor(d,{input,block}){
 return block('Página y formulario de reseñas',input('reviewPage.title','Título principal',{area:true})+input('reviewPage.intro','Presentación',{area:true})+Object.entries({formTitle:'Título del formulario',nameLabel:'Etiqueta del nombre',emailLabel:'Etiqueta del correo',interestLabel:'Etiqueta del servicio',ratingLabel:'Pregunta de calificación',messageLabel:'Etiqueta del comentario',messagePlaceholder:'Ayuda dentro del comentario',buttonLabel:'Texto del botón'}).map(([key,label])=>input('reviewPage.'+key,label)).join(''))+
 block('Encabezado del módulo de reseñas',input('widgets.reviews.title','Título')+input('widgets.reviews.intro','Descripción'))+
 block('Reseñas de Google · cargadas manualmente',(d.googleReviews?.items||[]).map((r,i)=>`<article class="admin-record"><h3>${e(r.name)} · ${e(r.rating)}/5</h3><p>${e(r.message)}</p>${input(`googleReviews.items.${i}.published`,'Mostrar reseña',{check:true})}</article>`).join(''))+
 '<section class="admin-block"><h3>Reseñas recibidas en la página</h3><p>Solo se pueden mostrar comentarios con autorización de publicación.</p><div id="received-reviews">Cargando…</div></section>';
}
